protected RetailSalesDiscountLine initRetailSalesDiscountLine(RetailSalesDiscountLine _discountLine, SalesLine _salesLine, Microsoft.Dynamics.Commerce.Runtime.DataModel.DiscountLine _crtDiscountLine)
{
    RetailSalesDiscountLine discountLine = next initRetailSalesDiscountLine(_discountLine, _salesLine, _crtDiscountLine);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        _discountLine.AppliedDiscountLineNum = _crtDiscountLine.LineNumber;
    }

    return discountLine;
}

protected void saveSalesOrder()
{
    next saveSalesOrder();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.updateGUPPricesHistory(crtSalesTransaction);
    }
}

public void setPricesDiscountsOnOrder(DiscPct _totalManualDiscountPercent)
{
    next setPricesDiscountsOnOrder(_totalManualDiscountPercent);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        System.Exception exception;

        try
        {
            SalesTable salesTable = SalesTable::find(salesId);

            if (salesTable.RecId == 0)
            {
                return;
            }

            this.createMarkupTransForSalesTable(salesTable);
            this.createMarkupTransForSalesLine(salesTable);

            SalesLine salesLine;
            select count(RecId) from salesLine
                where salesLine.SalesId == salesId;

            if (salesLine.RecId == 0)
            {
                return;
            }

            CLRObject clrFreeItemLines = this.calcuateFreeItemForOrder();
            if (clrFreeItemLines)
            {
                this.saveSalesOrderFreeItemLine(clrFreeItemLines);
            }
        }
        catch (Exception::CLRError)
        {
            exception = CLRInterop::getLastException();

            if (exception != null)
            {
                exception = exception.get_InnerException();

                if (exception != null)
                {
                    warning(exception.ToString());
                }
            }
        }
    }
}

private void createMarkupTransForSalesLine(SalesTable _salesTable)
{
    SalesLine salesLine;

    while select salesLine
        where salesLine.SalesId == _salesTable.SalesId
    {
        salesLine.createMarkupTrans(_salesTable, true);
    }
}

private CLRObject calcuateFreeItemForOrder()
{
    GUPAttributeBasedPricingDataManager attributeBasedPricingManager = new GUPAttributeBasedPricingDataManager(currentChannel.RecId, this.getTransactionId(), tempOrderItem, true);
    if (crtSalesTransaction)
    {
        return Microsoft.Dynamics.Commerce.Runtime.Services.AttributeBasedPricingEngine.FreeItemCalculator::CalculateFreeItems(
            attributeBasedPricingManager,
            crtSalesTransaction,
            currencyAndRoundingHelper,
            transactionCurrency,
            activeDateTimeOffset);
    }
    return null;
}

private void updateGUPPricesHistory(Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction crtSalesTransaction)
{
    if (crtSalesTransaction != null)
    {
        ttsBegin;

        CLRObject clrSalesLines, enumeratorSalesLine;
        CLRObject clrPriceLines, enumeratorPriceLine;
        SalesLine salesLine;

        GUPSalesBasePriceLineMap basePriceLineMap;

        str lineId;

        clrSalesLines = crtSalesTransaction.get_SalesLines();
        enumeratorSalesLine = clrSalesLines.GetEnumerator();
        while (enumeratorSalesLine.MoveNext())
        {
            Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine = enumeratorSalesLine.get_Current();
            lineId = crtSalesLine.get_LineId();

            if (crtLineIdCurrentLine && crtLineIdCurrentLine != lineId)
            {
                continue;
            }

            salesLine = SalesLine::findInventTransId(lineId);

            if (salesLine.InventTransId && salesLine.SalesStatus != SalesStatus::Invoiced && salesLine.SalesStatus != SalesStatus::Canceled)
            {
                // First delete all margin adjustment history
                GUPMarginComponentAdjustmentHistory::deleteHistory(salesLine.InventTransId);

                clrPriceLines = crtSalesLine.get_PriceLines();
                enumeratorPriceLine = clrPriceLines.GetEnumerator();
                while (enumeratorPriceLine.MoveNext())
                {
                    Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine crtPriceLine = enumeratorPriceLine.get_Current();

                    if (this.isPriceDetailsEnabled() && crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.BasePriceLine)
                    {
                        basePriceLineMap = this.initBasePriceLineMap(basePriceLineMap, crtPriceLine);
                    }

                    if (this.isPriceDetailsEnabled() && crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreementPriceLine)
                    {
                        basePriceLineMap.clear();
                        basePriceLineMap = this.initBasePriceLineMap(basePriceLineMap, crtPriceLine);
                    }

                    if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributePricingAdjustmentPriceLine)
                    {
                        Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributePricingAdjustmentPriceLine adjustmentPriceLine = crtPriceLine as Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributePricingAdjustmentPriceLine;

                        GUPPriceDetailsHelper::updateGUPMarginComponentAdjustmentHistory(
                        crtPriceLine.get_RecordId(),
                        -adjustmentPriceLine.get_AdjustedAmount(),
                        this.convertCrtPriceLinePriceMethodToDiscountMethodEnum(crtPriceLine.get_PriceMethod()),
                        salesLine);
                    }
                }

                if (basePriceLineMap.RefRecId)
                {
                    GUPPriceDetailsHelper::findOrCreateMCRPriceHistory(basePriceLineMap, salesLine);
                }
                else
                {
                    GUPPriceDetailsHelper::clearPriceHistory(salesLine);
                }

            }
        }

        ttscommit;
    }
}

private void saveSalesOrderFreeItemLine(CLRObject _clrFreeItemLines)
{
    if (this is RetailSalesOrderCalculator)
    {
        RetailSalesOrderCalculator retailSalesOrderCalculator = this as retailSalesOrderCalculator;
        SalesId salesIdCurrent = retailSalesOrderCalculator.getTransactionId();
        ttsbegin;

        SalesTable salesTable = SalesTable::find(salesIdCurrent);

        // delete those sales lines for free item but not exist in free item discount now.
        GUPFreeItemLine gupFreeItemLine;
        SalesLine salesLine;
        delete_from salesLine
        where salesLine.IsFreeItemLine == NoYes::Yes
            && salesLine.SalesId == salesIdCurrent
        notexists join gupFreeItemLine
            where gupFreeItemLine.RecId == salesLine.GUPFreeItemLineRecId;

        // delete those sales lines for free item which is disabled.
        GUPFreeItemDiscount freeItemDiscount;
        delete_from salesLine
        exists join gupFreeItemLine
            where gupFreeItemLine.RecId == salesLine.GUPFreeItemLineRecId
        exists join  freeItemDiscount
            where freeItemDiscount.OfferId == gupFreeItemLine.FreeItemId
                && freeItemDiscount.Status == RetailDisabledEnabled::Disabled
                && salesLine.SalesId == salesIdCurrent;

        // delete those sales lines for free item whose item id is changed
        InventTable inventTable;
        delete_from salesLine
        exists join gupFreeItemLine
            where gupFreeItemLine.RecId == salesLine.GUPFreeItemLineRecId
        exists join inventTable
            where inventTable.Product == gupFreeItemLine.Product
        exists join  freeItemDiscount
            where freeItemDiscount.OfferId == gupFreeItemLine.FreeItemId
                && freeItemDiscount.Status == RetailDisabledEnabled::Enabled
                && salesLine.SalesId == salesIdCurrent
                && salesLine.ItemId != inventTable.ItemId;

        CLRObject enumeratorFreeItemLines = _clrFreeItemLines.GetEnumerator();
        TmpRecIdFilter tmpRecIdFilter;
        while (enumeratorFreeItemLines.MoveNext())
        {
            Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine crtFreeItemLine = enumeratorFreeItemLines.get_Current();
            gupFreeItemLine = GUPFreeItemLine::findByCRTFreeItemLine(crtFreeItemLine);

            tmpRecIdFilter.RefRecId = gupFreeItemLine.RecId;
            tmpRecIdFilter.insert();

            select firstonly salesLine
            where salesLine.SalesId == salesIdCurrent
                && salesLine.IsFreeItemLine == NoYes::Yes
                && salesLine.GUPFreeItemLineRecId == gupFreeItemLine.RecId;
            if (salesLine.RecId)
            {
                if (salesLine.updateFromCRTFreeItemLine(crtFreeItemLine))
                {
                    salesLine.selectForUpdate(true);
                    salesLine.update();
                }
            }
            else
            {
                salesLine.clear();
                salesLine.initFromSalesTable(salesTable);
                salesLine.initFromFreeItemLine(crtFreeItemLine, gupFreeItemLine);
                salesLine.insert();

                RetailSalesLine retailSalesline = RetailSalesLine::findBySalesLine(salesLine.RecId, true);
                retailSalesline.IsPriceLocked = NoYes::Yes;
                retailSalesline.update();
            }
            salesLine.createOrUpdateRetailSalesDiscountLine(gupFreeItemLine);
        }

        delete_from salesLine
            where salesLine.SalesId == salesIdCurrent
                && salesLine.IsFreeItemLine == NoYes::Yes
            notexists join tmpRecIdFilter
                where tmpRecIdFilter.RefRecId == salesLine.GUPFreeItemLineRecId;

        ttscommit;
    }
}

protected Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction initializeCrtTransaction()
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction crtSalesTransactionLocal = next initializeCrtTransaction();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        utcDateTime sessionDateTime = DateTimeUtil::getSystemDateTime();

        var currencyCode = currentSalesLine.CurrencyCode != '' ? currentSalesLine.CurrencyCode : salesTable.CurrencyCode;

        CLRObject clrSalesLines, enumeratorSalesLine;
        clrSalesLines = crtSalesTransactionLocal.get_SalesLines();
        if (clrSalesLines.get_Count() > 0)
        {
            enumeratorSalesLine = clrSalesLines.GetEnumerator();
            enumeratorSalesLine.MoveNext();
            Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine = enumeratorSalesLine.get_Current();
            System.DateTimeOffset salesDate = crtSalesLine.SalesDate;
            sessionDateTime = DateTimeUtil::parse(salesDate.ToString("yyyy-MM-ddThh:mm:ss"));
        }

        this.initializeCrt(retailSalesTable.RetailChannel, salesTable.CustAccount, currencyCode, sessionDateTime);

        this.setPriceTreeName();
    }

    return crtSalesTransactionLocal;
}

private void setPriceTreeName()
{
    GUPPriceTreeName gupPriceTreeName = GUPPricingTree::findPriceTreeNameBySalesId(this.salesId);

    if (this.pricingManager)
    {
        GUPRetailPricingDataManager gupPricingManager = this.pricingManager;
        Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter unifiedPricingParameter = gupPricingManager.GetGlobalUnifiedPricingParameter();
        unifiedPricingParameter.PriceTreeName = gupPriceTreeName;
    }
}

protected RetailSalesOrderCalculatorResult doGetCalculationResult()
{
    RetailSalesOrderCalculatorResult result = next doGetCalculationResult(); 

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && this.isPriceDetailsEnabled())
    {
        Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine;
        CLRObject clrSalesLines, enumeratorSalesLine;
        Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine crtPriceLine;
        CLRObject clrPriceLines, enumeratorPriceLine;

        GUPSalesBasePriceLineMap basePriceLineMap;
        str lineId;

        clrSalesLines = crtSalesTransaction.get_SalesLines();

        enumeratorSalesLine = clrSalesLines.GetEnumerator();
        while (enumeratorSalesLine.MoveNext())
        {
            crtSalesLine = enumeratorSalesLine.get_Current();

            lineId = crtSalesLine.get_LineId();
            if (lineId == crtLineIdCurrentLine)
            {
                clrPriceLines = crtSalesLine.get_PriceLines();
                enumeratorPriceLine = clrPriceLines.GetEnumerator();
                while (enumeratorPriceLine.MoveNext())
                {
                    crtPriceLine = enumeratorPriceLine.get_Current();

                    if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.BasePriceLine)
                    {
                        basePriceLineMap = this.initBasePriceLineMap(basePriceLineMap, crtPriceLine);
                    }

                    if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreementPriceLine)
                    {
                        basePriceLineMap.clear();
                        basePriceLineMap = this.initBasePriceLineMap(basePriceLineMap, crtPriceLine);
                    }
                }

                if (basePriceLineMap.RefRecId)
                {
                    result.addBasePriceLine(basePriceLineMap);
                }
            }
        }
    }

    return result;
}

protected GUPSalesBasePriceLineMap initBasePriceLineMap(GUPSalesBasePriceLineMap _basePriceLineMap, Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine _crtPriceLine)
{
    if (_crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.BasePriceLine)
    {
        GUPItemBasePrice vendorListPrice = GUPItemBasePrice::findRecId(_crtPriceLine.get_RecordId());
        if (vendorListPrice)
        {
            this.initFromVendorlistPrice(_basePriceLineMap, vendorListPrice);
        }
    }
    else if (_crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreementPriceLine)
    {
        PriceDiscTable priceDiscTable = PriceDiscTable::findRecId(_crtPriceLine.get_RecordId());
        if (priceDiscTable)
        {
            this.initFromPriceDiscTable(_basePriceLineMap, priceDiscTable);
        }
    }

    return _basePriceLineMap;
}

private ModuleInventCustVend convertVendorListPriceType(GUPBasePriceType _basePriceType)
{
    ModuleInventCustVend priceModule;

    switch (_basePriceType)
    {
        case GUPBasePriceType::BasePriceInventoryCost:
            priceModule =  ModuleInventCustVend::Invent;
            break;
        case GUPBasePriceType::BasePricePurchase:
            priceModule =  ModuleInventCustVend::Vend;
            break;
        case GUPBasePriceType::BasePriceSales:
            default:
            priceModule = ModuleInventCustVend::Cust;
            break;
    }

    return priceModule;
}

private void initFromPriceDiscTable(GUPSalesBasePriceLineMap _basePriceLineMap, PriceDiscTable _priceDiscTable)
{
    _basePriceLineMap.RefTableId             = _priceDiscTable.TableId;
    _basePriceLineMap.RefRecId               = _priceDiscTable.RecId;
    _basePriceLineMap.AccountCode            = _priceDiscTable.AccountCode;
    _basePriceLineMap.AccountRelation        = _priceDiscTable.AccountRelation;
    _basePriceLineMap.ItemCode               = _priceDiscTable.ItemCode;
    _basePriceLineMap.ItemRelation           = _priceDiscTable.ItemRelation;
    _basePriceLineMap.Amount                 = _priceDiscTable.Amount;
    _basePriceLineMap.Currency               = _priceDiscTable.Currency;
    _basePriceLineMap.FromDate               = _priceDiscTable.FromDate;
    _basePriceLineMap.InventDimId            = _priceDiscTable.InventDimId;
    _basePriceLineMap.Markup                 = _priceDiscTable.Markup;
    _basePriceLineMap.AllocateMarkup         = _priceDiscTable.AllocateMarkup;
    _basePriceLineMap.Module                 = _priceDiscTable.Module;
    _basePriceLineMap.Percent1               = _priceDiscTable.Percent1;
    _basePriceLineMap.Percent2               = _priceDiscTable.Percent2;
    _basePriceLineMap.PriceUnit              = _priceDiscTable.PriceUnit;
    _basePriceLineMap.QuantityAmount         = _priceDiscTable.QuantityAmountFrom;
    _basePriceLineMap.QuantityAmountTo       = _priceDiscTable.QuantityAmountTo;
    _basePriceLineMap.Relation               = _priceDiscTable.Relation;
    _basePriceLineMap.UnitId                 = _priceDiscTable.UnitId;

    PriceDiscAdmTrans priceDiscAdmTrans;
    select firstonly priceDiscAdmTrans where priceDiscAdmTrans.RecId == _priceDiscTable.OriginalPriceDiscAdmTransRecId;
    _basePriceLineMap.JournalNum = priceDiscAdmTrans.JournalNum;

    if (_priceDiscTable.PriceComponentCombination)
    {
        _basePriceLineMap.PriceComponentCode = GUPPriceComponentCodePriceAttributeGroupCombination::find(_priceDiscTable.PriceComponentCombination).PriceComponentCodeName;
    }
}
